// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public {
        c = new MyContract();
        vm.deal(address(c), 1 ether);
    }
    function testFuzz_property(uint256 amount, address receiver) public {
        address owner = address(this);
        amount = bound(amount, 2, address(c).balance);
        vm.assume(receiver != address(0));
        uint256 receiverBefore = receiver.balance;
        vm.prank(owner);
        c.sendTo(receiver, amount);
        assertTrue(receiver.balance == receiverBefore + amount);
    }
}
